SELECT * FROM jsonb_to_recordset($reviewed$[{"id":"5c50aed9-ea2a-403b-be8e-cc9f12c92b5c","claim_key":"official-profile:taichung-city-council-current-councilors:d77fb63825f9:7d81d2a2-d94f-45de-97e8-d473e046dd85:platform","person_id":"7d81d2a2-d94f-45de-97e8-d473e046dd85","candidate_id":"09e94143-62ca-491f-83e9-eaf0c286e649","name":"江和樹","source_url":"https://www.tccc.gov.tw/wb_introduction02.asp?uno=&zno=107&cno=79","source_sha256":null,"after_text":"老有所依\n•愛心廚房弱勢共餐\n•長照升級\n•廣設無障礙\n幼有所養\n• 課後托育\n• 增設非營利幼兒園\n•單親喘息照顧\n行有處所\n•增設公有停車場\n•爭取捷運線到屯區\n•改善74號匝道堵塞\n浪有所歸\n•爭取屯區寵物公園\n•飼主教育養成課程\n•爭取毛孩絕育補助預算增加\n居有定所\n•監督中火轉型進度\n•爭取社宅租金平價化\n•爭取霧峰國宅建設","items":["老有所依：愛心廚房弱勢共餐","老有所依：長照升級","老有所依：廣設無障礙","幼有所養：課後托育","幼有所養：增設非營利幼兒園","幼有所養：單親喘息照顧","行有處所：增設公有停車場","行有處所：爭取捷運線到屯區","行有處所：改善74號匝道堵塞","浪有所歸：爭取屯區寵物公園","浪有所歸：飼主教育養成課程","浪有所歸：爭取毛孩絕育補助預算增加","居有定所：監督中火轉型進度","居有定所：爭取社宅租金平價化","居有定所：爭取霧峰國宅建設"],"intro":"","allowed_text_md5":["5daf3d1b24db97c41ca108bfb3b56d0b"],"allowed_splits":[{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"needs_review","releaseQuality":{"version":"platform-fulfillment-release-v2","reasonCodes":["post_deployment_quality_review"]}}],"old_items":null,"before_review_status":"verified","before_visibility":"public","before_is_public":true},{"id":"2be8c899-a296-46d9-a2ee-88cdb145f0dd","claim_key":"cec-platform:2022:votetw-candidate-1300bb619496643b","person_id":"a2cc1ed1-e714-4e56-9416-0dcabae72277","candidate_id":"2623a249-4ac3-4da1-b37d-17d08b641a31","name":"張善政","source_url":"https://eebulletin.cec.gov.tw/111/04%E6%A1%83%E5%9C%92%E5%B8%82/01%E5%B8%82%E9%95%B7/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC3%E5%B1%86%E5%B8%82%E9%95%B7%E9%81%B8%E8%88%89%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf","source_sha256":"79d3c37e903101d4bd0a539856ba3aadd4119e9e61782d41d0b93e9c32ae6d19","after_text":"未來幾年是桃園發展的黃金時期，是桃園「轉骨」、升級的關鍵。讓善哥和你一起拚！桃園善好的未來！\n台灣的幸福宜居家園\n1. 多都心策略發展\n針對區域特色與分區發展需求，以「產業、效率、永續」為目標，推動多都心生活圈都市計畫，籌劃創新的產業發展科技園區。\n2. 鐵路捷運新風貌\n以都市設計為基礎，將鐵路地下化原地構築林園大道，打造具區域特色與生活美學的生活環境。\n3. 交通更便利\n於加速捷運系統建設同時，推動公車加YouBike免費「幸福里程」。改善通學與通勤步行環境，打造大眾運輸與友善步行低碳城市。構建國道與地區客運轉運站，擴大公車轉乘優惠範圍。改善物流業基地附近交通，闢建專用園區。\n4. 游憩環境更優質\n打造更豐富親水遊憩空間。規劃運動園區，結合公辦與民間資源建立微型運動據點。廣設社區共融遊戲特色公園，提升兒童遊樂質量。\n5. 人人更健康\n鼓勵基層醫療院所投入維護社區民眾健康、完善各項慢性病的服務。\n6. 安老更快樂\n結合關懷據點增設社區長照站及長照中心，發展活躍、健康、在地老化的友善環境。\n7. 桃園更好玩\n配合自然地景、地方慶典、運動觀光、特色產業等多元主題推動深度旅遊，成為北台灣民眾共享桃花園。\n8. 桃園．我的家\n加強保存展現客家、閩南、眷村、原住民、新住民、滇緬等多族群的歷史與文化。\n亞洲的智慧科技新都\n1. 產業更智慧\n推動工業4.0、數位／智慧升級。輔導農業運用新科技生產及廣銷，推廣高附加價值新農業。\n2. 城市更數位\n以桃園作為新科技試驗、發展及落實於市政應用之基地。建立數位世界「孿生桃園」，展現桃園過去與未來之風貌。打造桃園成為亞洲數位新科技重要市場，吸引投資與創業。\n3. 教育更均衡\n推行科技普及教育，增加科技素養、設計思考及生活應用。培育偏鄉師資，搭配遠距教學，減少城鄉教育落差。\n青年的安家立業基地\n1. 居住不煩惱\n增建青年、勞工住宅，提供平價且工作、生活、教育皆便利的幸福家園。\n2. 育兒更無憂\n增加公托、準公托規模，補助托嬰、育兒與學前教育，擴充義務教育能量，在學區內安心就學。\n3. 創業不愁錢\n成立桃青基金投資新創，協助新創進軍國際。\n4. 能力好發揮\n支持青年投入工業4.0、科技施政、數位孿生桃園等產業，打造多元高薪在地工作機會，優先補助青年擔任喜好之創業主題（如軟體與網路、電競、設計文創、社會創新等）。\n5. 創意好展現\n闢建充裕的青年表演、策展、創作空間，融合到市民日常生活。\n充滿機會","items":["台灣的幸福宜居家園：多都心策略發展\n針對區域特色與分區發展需求，以「產業、效率、永續」為目標，推動多都心生活圈都市計畫，籌劃創新的產業發展科技園區。","台灣的幸福宜居家園：鐵路捷運新風貌\n以都市設計為基礎，將鐵路地下化原地構築林園大道，打造具區域特色與生活美學的生活環境。","台灣的幸福宜居家園：交通更便利\n於加速捷運系統建設同時，推動公車加YouBike免費「幸福里程」。改善通學與通勤步行環境，打造大眾運輸與友善步行低碳城市。構建國道與地區客運轉運站，擴大公車轉乘優惠範圍。改善物流業基地附近交通，闢建專用園區。","台灣的幸福宜居家園：游憩環境更優質\n打造更豐富親水遊憩空間。規劃運動園區，結合公辦與民間資源建立微型運動據點。廣設社區共融遊戲特色公園，提升兒童遊樂質量。","台灣的幸福宜居家園：人人更健康\n鼓勵基層醫療院所投入維護社區民眾健康、完善各項慢性病的服務。","台灣的幸福宜居家園：安老更快樂\n結合關懷據點增設社區長照站及長照中心，發展活躍、健康、在地老化的友善環境。","台灣的幸福宜居家園：桃園更好玩\n配合自然地景、地方慶典、運動觀光、特色產業等多元主題推動深度旅遊，成為北台灣民眾共享桃花園。","台灣的幸福宜居家園：桃園．我的家\n加強保存展現客家、閩南、眷村、原住民、新住民、滇緬等多族群的歷史與文化。","亞洲的智慧科技新都：產業更智慧\n推動工業4.0、數位／智慧升級。輔導農業運用新科技生產及廣銷，推廣高附加價值新農業。","亞洲的智慧科技新都：城市更數位\n以桃園作為新科技試驗、發展及落實於市政應用之基地。建立數位世界「孿生桃園」，展現桃園過去與未來之風貌。打造桃園成為亞洲數位新科技重要市場，吸引投資與創業。","亞洲的智慧科技新都：教育更均衡\n推行科技普及教育，增加科技素養、設計思考及生活應用。培育偏鄉師資，搭配遠距教學，減少城鄉教育落差。","青年的安家立業基地：居住不煩惱\n增建青年、勞工住宅，提供平價且工作、生活、教育皆便利的幸福家園。","青年的安家立業基地：育兒更無憂\n增加公托、準公托規模，補助托嬰、育兒與學前教育，擴充義務教育能量，在學區內安心就學。","青年的安家立業基地：創業不愁錢\n成立桃青基金投資新創，協助新創進軍國際。","青年的安家立業基地：能力好發揮\n支持青年投入工業4.0、科技施政、數位孿生桃園等產業，打造多元高薪在地工作機會，優先補助青年擔任喜好之創業主題（如軟體與網路、電競、設計文創、社會創新等）。","青年的安家立業基地：創意好展現\n闢建充裕的青年表演、策展、創作空間，融合到市民日常生活。"],"intro":"未來幾年是桃園發展的黃金時期，是桃園「轉骨」、升級的關鍵。讓善哥和你一起拚！桃園善好的未來！\n充滿機會","allowed_text_md5":["6837ce8230923d6f08618719340626e9","5757029a481d3a129930da53955d1d17"],"allowed_splits":[null],"old_items":null,"before_review_status":"verified","before_visibility":"public","before_is_public":true},{"id":"383db1cc-e8d0-4ea6-ba94-80168c6a3383","claim_key":"cec-platform:2022:votetw-candidate-9a24cd9e4b77f3f2","person_id":"a0a3f247-d1dd-4480-8725-a7c8f2a5393f","candidate_id":"27640d4a-87c0-4630-b06c-596a5946b249","name":"高虹安","source_url":"https://eebulletin.cec.gov.tw/111/22%E6%96%B0%E7%AB%B9%E5%B8%82/01%E5%B8%82%E9%95%B7/%E6%96%B0%E7%AB%B9%E5%B8%82%E5%B8%82%E9%95%B7.pdf","source_sha256":"7564b76c9db922898c86d509ad025d2407888d4d1841c479afbf4bf23778a7e4","after_text":"誠懇務實，我們的城市語言\n用科學的方法、產業的執行力，打造智慧、共融、創新的新竹市\n教育文化\n1. 推動國中小智慧教室、建置竹課雲線上學習系統。\n2. 完善示範型先導雙語學校，引進國際認證課程，提升雙語師資、建置完整教材。\n3. 開辦安心通學交通車，打造無憂通學步道，促進就近入學。\n4. 落實校園營養午餐三章一Q補助，食材在地化，學童吃得安心又減碳。\n5. 設置校園霸凌事件單一處理窗口、建置防治校園毒品通報網絡。\n6. 聘足體育音樂專長師資，積極鼓勵社團、校隊參與國內外競賽。\n7. 推動藝術展演活動、藝文空間、美學教育，提升市民文化品質。\n宜居永續\n1. 健全都市水循環，打造海綿城市，降低地區淹水風險。\n2. 維護市民生活環境品質，推動綠屋頂計畫，廣植植被，改善空氣品質，為城市降溫。\n3. 提出淨零碳排路徑策略，打造友善綠運輸環境，推動低碳交通。\n都市發展\n1. 加速提升公共汙水下水道接管普及率，改善供水管網，落實喝好水訴求。\n2. 加速推動都市更新、危老重建、市容改善，落實都市計畫管理，平衡地區發展。\n3. 興建光埔全區空橋，提供安全舒適通學通勤人行空間。\n經濟繁榮\n1. 推動舊城復興、特色夜市、商圈重生，加速市場改建和設施改善。\n2. 公道五沿線產業2.0升級，加速香山工業區轉型活化。\n3. 打造「新竹安心創」新創青創支持體系。\n4. 加速推動延宕多年的新竹果菜批發市場搬建計畫，健全果菜批發市場管理機制。\n5. 規劃假日觀光巴士，串連新竹景點、文資與商圈。\n世代共融\n1. 友善婚育生養環境，增進幼托量能品質，提高幼教補助，減輕家長負擔。\n2. 延續現有老人福利，升級敬老愛心卡項目點數，打造完整友善長照環境。\n3. 落實身心障礙六大平權，推動進步新竹無障礙空間，打造共融式遊戲場。\n4. 新建社會住宅，推動年輕家庭租屋補貼。\n5. 推動多元族群共融社會，促進客家、原民、新住民、穆斯林等文化和諧發展。\n6. 建立動物友善環境空間，完善動物福祉。\n交通暢行\n1. 優化公車路線，汰換為低底盤公車，服務年長、身障者搭乘，並推動幹線公車乘車優惠。\n2. 透過鄰里巷道及易肇事路段交通改善措施，強化道路交通安全通暢。\n3. 加速新建立體停車場，紓緩市區停車日益嚴重問題。\n4. 積極向中央爭取補助經費，加速推動各項指標道路建設工程，建構完整交通路網，紓解園區交通壅塞。\n5. 運用大數據和AI技術，建構共享綠能、智慧、安全的交通環境。\n開放對話\n1. 成立新竹縣市政府整合溝通平台，促進大新竹生活圈共好。\n2. 建置公民參與市政平台、參與式預算機制。\n3. 推動城市開放資料，完善資料結構化，加速應用開發。\n4. 引入智慧城市科技，以新竹通APP整合市民服務。\n城市更新，新竹安心","items":["教育文化：推動國中小智慧教室、建置竹課雲線上學習系統。","教育文化：完善示範型先導雙語學校，引進國際認證課程，提升雙語師資、建置完整教材。","教育文化：開辦安心通學交通車，打造無憂通學步道，促進就近入學。","教育文化：落實校園營養午餐三章一Q補助，食材在地化，學童吃得安心又減碳。","教育文化：設置校園霸凌事件單一處理窗口、建置防治校園毒品通報網絡。","教育文化：聘足體育音樂專長師資，積極鼓勵社團、校隊參與國內外競賽。","教育文化：推動藝術展演活動、藝文空間、美學教育，提升市民文化品質。","宜居永續：健全都市水循環，打造海綿城市，降低地區淹水風險。","宜居永續：維護市民生活環境品質，推動綠屋頂計畫，廣植植被，改善空氣品質，為城市降溫。","宜居永續：提出淨零碳排路徑策略，打造友善綠運輸環境，推動低碳交通。","都市發展：加速提升公共汙水下水道接管普及率，改善供水管網，落實喝好水訴求。","都市發展：加速推動都市更新、危老重建、市容改善，落實都市計畫管理，平衡地區發展。","都市發展：興建光埔全區空橋，提供安全舒適通學通勤人行空間。","經濟繁榮：推動舊城復興、特色夜市、商圈重生，加速市場改建和設施改善。","經濟繁榮：公道五沿線產業2.0升級，加速香山工業區轉型活化。","經濟繁榮：打造「新竹安心創」新創青創支持體系。","經濟繁榮：加速推動延宕多年的新竹果菜批發市場搬建計畫，健全果菜批發市場管理機制。","經濟繁榮：規劃假日觀光巴士，串連新竹景點、文資與商圈。","世代共融：友善婚育生養環境，增進幼托量能品質，提高幼教補助，減輕家長負擔。","世代共融：延續現有老人福利，升級敬老愛心卡項目點數，打造完整友善長照環境。","世代共融：落實身心障礙六大平權，推動進步新竹無障礙空間，打造共融式遊戲場。","世代共融：新建社會住宅，推動年輕家庭租屋補貼。","世代共融：推動多元族群共融社會，促進客家、原民、新住民、穆斯林等文化和諧發展。","世代共融：建立動物友善環境空間，完善動物福祉。","交通暢行：優化公車路線，汰換為低底盤公車，服務年長、身障者搭乘，並推動幹線公車乘車優惠。","交通暢行：透過鄰里巷道及易肇事路段交通改善措施，強化道路交通安全通暢。","交通暢行：加速新建立體停車場，紓緩市區停車日益嚴重問題。","交通暢行：積極向中央爭取補助經費，加速推動各項指標道路建設工程，建構完整交通路網，紓解園區交通壅塞。","交通暢行：運用大數據和AI技術，建構共享綠能、智慧、安全的交通環境。","開放對話：成立新竹縣市政府整合溝通平台，促進大新竹生活圈共好。","開放對話：建置公民參與市政平台、參與式預算機制。","開放對話：推動城市開放資料，完善資料結構化，加速應用開發。","開放對話：引入智慧城市科技，以新竹通APP整合市民服務。"],"intro":"誠懇務實，我們的城市語言\n用科學的方法、產業的執行力，打造智慧、共融、創新的新竹市\n城市更新，新竹安心","allowed_text_md5":["8e3832c734a46cb419b09dc73f6270b6","849480af21aa0713c450d2a8d7d58519"],"allowed_splits":[null],"old_items":null,"before_review_status":"verified","before_visibility":"public","before_is_public":true},{"id":"156e4558-0a6f-42e0-8672-69c73ad12490","claim_key":"cec-platform:2022:votetw-candidate-ef582d7c964477a6","person_id":"e0e9a15e-433a-487c-b73f-f204694ec20b","candidate_id":"48edb935-85d3-499a-8c8a-89c816acdb37","name":"施佩妤","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"1a24ea8cde558867ed475f9d7d207b9f4158ac980a77e2b33108302573e081bf","after_text":"● 學育並進\n1. 吃在地、食當季，支持縣府推動營養午餐免費，鼓勵學校採用在地食材，爭取提高一成餐費，讓學童更均衡營養\n2. 推動企業認養從小學課後照顧，讓家長減輕負擔、安心打拼\n3. 增加閱讀場域，延長圖書館閉館時間至晚上8點\n4. 推動親子共享、共讀、共學，藉由陪伴增進親子關係\n5. 維護校園安全，爭取校園守衛\n\n● 永續農業\n1. 因應淨零排放政策，支持推動循環農業、減碳環保，將農業剩餘資源、廢棄物再利用，達到減碳目標\n2. 推動景觀作物專區，以維護農田地力，結合在地觀光產業，提高農田利用\n\n● 社福加值\n1. 爭取增加幸福長青卡使用品項，如搭乘計程車等交通工具\n2. 爭取搭乘公車距離6公里內免費\n3. 結合民間產業，提供關懷據點共餐之水果品項\n4. 推動學校社區化，妥適利用校園公共空間\n5. 爭取設置共融式遊具，滿足孩子的遊戲需求\n6. 爭取警消軟硬體設備的更新或增設\n7. 提升警消保險等相關保障的加強\n8. 輔導新住民融入在地文化，爭取辦理各項交流活動\n9. 推動整合公寓大廈成立管委會，加強大樓公共安全\n10. 督促公共空間無障礙設施檢核，落實環境友善空間\n\n● 完善長照\n1. 配合長照2.0審視閒置空間，廣設巷弄長照站\n2. 增加社區長青運動設施及空間\n3. 輔導社區增設關懷據點，讓銀髮長輩能在地樂活、在地安養\n\n● 文化耕耘\n1. 深耕文化，爭取更多藝術家展演平台，拓展藝術能量\n2. 推廣傳統工藝技術，傳承並向下扎根\n3. 監督管理文化資產，保存原有的地方紋理\n4. 支持縣府推動老屋活化政策，守護歷史建物\n5. 輔導廟宇紀錄其文化、並發展一廟一特色，落實民俗的推廣與傳承\n\n● 全民體育\n1. 爭取興建國民暨兒童親子館及運動中心\n2. 改善現有運動環境、完備各項體育設施\n3. 增設社區長青運動空間及器材\n4. 推動全民運動，舉辦各項類別體育季\n\n● 觀光經濟\n1. 推動央廣打造為文創園區及觀光市集，造就地方就業機會\n2. 輔導特色社區，增添觀光深度、並開拓鄉村觀光商機\n\n● 青年發展\n1. 支持青年創業與輔導返鄉規劃\n2. 整合各方資源，提供青農、青商、青文（文史工作）最有利輔導與輔助\n3. 爭取福鹿秀設立青年住宅\n\n● 寵物友善\n1. 爭取設立寵物公園\n2. 推廣輔導飼主良好的飼養習慣，打造人與寵物共好的環境\n3. 協助推行下鄉絕育，推動毛小孩結紮，並鼓勵認養不棄養，以解決流浪動物問題\n\n● 熱忱服務\n1. 協助醫療、急難救助等相關事宜\n2. 服務處提供律師免費法律諮詢","items":["學育並進：吃在地、食當季，支持縣府推動營養午餐免費，鼓勵學校採用在地食材，爭取提高一成餐費，讓學童更均衡營養","學育並進：推動企業認養從小學課後照顧，讓家長減輕負擔、安心打拼","學育並進：增加閱讀場域，延長圖書館閉館時間至晚上8點","學育並進：推動親子共享、共讀、共學，藉由陪伴增進親子關係","學育並進：維護校園安全，爭取校園守衛","永續農業：因應淨零排放政策，支持推動循環農業、減碳環保，將農業剩餘資源、廢棄物再利用，達到減碳目標","永續農業：推動景觀作物專區，以維護農田地力，結合在地觀光產業，提高農田利用","社福加值：爭取增加幸福長青卡使用品項，如搭乘計程車等交通工具","社福加值：爭取搭乘公車距離6公里內免費","社福加值：結合民間產業，提供關懷據點共餐之水果品項","社福加值：推動學校社區化，妥適利用校園公共空間","社福加值：爭取設置共融式遊具，滿足孩子的遊戲需求","社福加值：爭取警消軟硬體設備的更新或增設","社福加值：提升警消保險等相關保障的加強","社福加值：輔導新住民融入在地文化，爭取辦理各項交流活動","社福加值：推動整合公寓大廈成立管委會，加強大樓公共安全","社福加值：督促公共空間無障礙設施檢核，落實環境友善空間","完善長照：配合長照2.0審視閒置空間，廣設巷弄長照站","完善長照：增加社區長青運動設施及空間","完善長照：輔導社區增設關懷據點，讓銀髮長輩能在地樂活、在地安養","文化耕耘：深耕文化，爭取更多藝術家展演平台，拓展藝術能量","文化耕耘：推廣傳統工藝技術，傳承並向下扎根","文化耕耘：監督管理文化資產，保存原有的地方紋理","文化耕耘：支持縣府推動老屋活化政策，守護歷史建物","文化耕耘：輔導廟宇紀錄其文化、並發展一廟一特色，落實民俗的推廣與傳承","全民體育：爭取興建國民暨兒童親子館及運動中心","全民體育：改善現有運動環境、完備各項體育設施","全民體育：增設社區長青運動空間及器材","全民體育：推動全民運動，舉辦各項類別體育季","觀光經濟：推動央廣打造為文創園區及觀光市集，造就地方就業機會","觀光經濟：輔導特色社區，增添觀光深度、並開拓鄉村觀光商機","青年發展：支持青年創業與輔導返鄉規劃","青年發展：整合各方資源，提供青農、青商、青文（文史工作）最有利輔導與輔助","青年發展：爭取福鹿秀設立青年住宅","寵物友善：爭取設立寵物公園","寵物友善：推廣輔導飼主良好的飼養習慣，打造人與寵物共好的環境","寵物友善：協助推行下鄉絕育，推動毛小孩結紮，並鼓勵認養不棄養，以解決流浪動物問題","熱忱服務：協助醫療、急難救助等相關事宜","熱忱服務：服務處提供律師免費法律諮詢"],"intro":"","allowed_text_md5":["ea8beb926277cf452974041591cf6b1b","550048e1ca5c7a0836a5947f4d7704e7"],"allowed_splits":[{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"needs_review","releaseQuality":{"version":"platform-fulfillment-release-v2","reasonCodes":["post_deployment_quality_review"]}}],"old_items":null,"before_review_status":"verified","before_visibility":"public","before_is_public":true},{"id":"1a1955cb-1282-4675-931e-103a3d5f9ce3","claim_key":"cec-platform:2022:votetw-candidate-f3fa567579c2e3d0","person_id":"00065cc7-0c8b-4ffb-abe2-3c0a13e124c3","candidate_id":"6186e004-7aa7-478f-a885-b2199d8472e4","name":"王惠美","source_url":"https://eebulletin.cec.gov.tw/111/10%E5%BD%B0%E5%8C%96%E7%B8%A3/01%E7%B8%A3%E9%95%B7/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%B8%A3%E9%95%B7%20.pdf","source_sha256":"41c7a77a796262c4c399b17188613dc71631bc2027ae879664cf2d506c11b406","after_text":"一、宜居彰化\n持續推進五大都市計劃，塑造城鄉新風貌；成立「彰化縣都市及住宅更新中心」，全面改造彰化老舊城區\n二、創薪彰化\n打造五大青創園區，成立青創孵化中心；從生產到行銷，提供青農一條龍式協助；提供青年住宅2.0，平價住宅輕鬆購；縣籍大專學生返鄉就業，學貸\n免利息；創薪加倍領2.0版；暢通求職求才管道，協助縣民適性及穩定就業；強化守法概念，打造友善就業環境\n三、進擊彰化\n提供婦女生育健檢輔助及免費坐月子到宅服務：0至2歲公托倍增計劃；彰化校園e指通2.0，學校訊息家長不漏接，科技校園安全維護，學生安心學\n習；建置元宇宙教育雲，虛擬實境學習不間斷，學習無國界；推動非教條式的禮義廉恥品德教育\n四、樂齡彰化\n全面建置不老健身房；長青幸福卡健康加倍計畫；持續提升衛生保健服務措施，建立一個可長可久的銀髮照顧系統\n五、便捷彰化\n加速四大軌道、規劃捷運和美線；完善縣內交通路網；推動路平三部曲、建構以人為本的路行空間；建置七大轉運站及幸福候車計畫\n六、樂活彰化\n一鄉鎮一特色公園；八卦山脈遊憩環境優化；打造西濱生態海岸樂園、溪州糖鐵國家綠道、田中水與綠生活空間\n七、永續彰化\n打造東螺、二林雙溪河畔新亮點、烏溪親水休閒運動空間營造、八堡圳水岸廊道，創造宜居水環境；發展綠經濟循環農業，提升農業廢棄資材資源\n化；推動淨零綠生活響應，打造節能低碳城市；提供電動公車新服務\n八、智慧彰化\n打造智慧海港城；運用3D與AR技術，發展智慧觀光；打造智慧防洪軔性城市；持續推動智慧農業；空污全區AI智慧監控，全區空品守護","items":["宜居彰化：持續推進五大都市計劃，塑造城鄉新風貌；成立「彰化縣都市及住宅更新中心」，全面改造彰化老舊城區","創薪彰化：打造五大青創園區，成立青創孵化中心；從生產到行銷，提供青農一條龍式協助；提供青年住宅2.0，平價住宅輕鬆購；縣籍大專學生返鄉就業，學貸免利息；創薪加倍領2.0版；暢通求職求才管道，協助縣民適性及穩定就業；強化守法概念，打造友善就業環境","進擊彰化：提供婦女生育健檢輔助及免費坐月子到宅服務：0至2歲公托倍增計劃；彰化校園e指通2.0，學校訊息家長不漏接，科技校園安全維護，學生安心學習；建置元宇宙教育雲，虛擬實境學習不間斷，學習無國界；推動非教條式的禮義廉恥品德教育","樂齡彰化：全面建置不老健身房；長青幸福卡健康加倍計畫；持續提升衛生保健服務措施，建立一個可長可久的銀髮照顧系統","便捷彰化：加速四大軌道、規劃捷運和美線；完善縣內交通路網；推動路平三部曲、建構以人為本的路行空間；建置七大轉運站及幸福候車計畫","樂活彰化：一鄉鎮一特色公園；八卦山脈遊憩環境優化；打造西濱生態海岸樂園、溪州糖鐵國家綠道、田中水與綠生活空間","永續彰化：打造東螺、二林雙溪河畔新亮點、烏溪親水休閒運動空間營造、八堡圳水岸廊道，創造宜居水環境；發展綠經濟循環農業，提升農業廢棄資材資源化；推動淨零綠生活響應，打造節能低碳城市；提供電動公車新服務","智慧彰化：打造智慧海港城；運用3D與AR技術，發展智慧觀光；打造智慧防洪軔性城市；持續推動智慧農業；空污全區AI智慧監控，全區空品守護"],"intro":"","allowed_text_md5":["f9a1333112bd9034dd7a792658131e05"],"allowed_splits":[null],"old_items":null,"before_review_status":"verified","before_visibility":"public","before_is_public":true},{"id":"05d68edd-369f-4c89-9cfb-1dd04c54c43d","claim_key":"cec-platform:2022:votetw-candidate-986796549ec1942c","person_id":"8f799cd1-9735-4c72-b121-36ded84a5914","candidate_id":"a8499810-bf7b-4b85-ac46-6e9cbc521423","name":"張麗善","source_url":"https://eebulletin.cec.gov.tw/111/12%E9%9B%B2%E6%9E%97%E7%B8%A3/01%E7%B8%A3%E9%95%B7/%E9%9B%B2%E6%9E%97%E7%B8%A3%E7%B8%A3%E9%95%B7.pdf","source_sha256":"81e89027cdf8370449ce759c58f5fef3e293b1804806cc81404b851dff6bc4d7","after_text":"雲林已成功上場！\n過去四年我們推動雲林的結構性轉型，優化雲林的社福、教育、循環經濟、觀光與產業數位轉型，成功吸引超過1,777億的投資。\n未來四年我們將加速前進，讓雲林脫胎換骨。\n除繼續強化雲林各項基礎建設、優化產業投資環境，擴大開發麥寮綜合商港外，並將興建高鐵體育園區，籌辦114年全國運動會，同時爭取設立雲東和雲西國家風景區。\n「2030 前進雲林」施政藍圖將聚焦於四大面向，涵蓋30項政策目標，推升雲林於2030年時蛻變為硬核且永續的農工商科技城。\n智慧經濟\n1. 數位零距離\n2. 永續農業\n3. 產業永續及智慧轉型\n4. 讓青年作文創的主人\n5. 觀光行銷2000+\n6. 暢流雲林\n7. 大健康產業\n低碳永續\n1. 雲林縣2030 SDGs\n2. 淨零減碳\n3. 雙語教育接軌國際\n4. 韌性防災\n5. 偏鄉無礙\n6. 綠能不缺電\n7. 拓展友善的生態保育\n安全健康\n1. 建構堅韌的社會安全網\n2. 公共場域零災害\n3. 雲林有心、食在安心\n4. 道安資訊智慧化\n5. 健康 i 運動\n6. 雲林．美哉．美在\n7. 後疫情新生活\n共融發展\n1. 活躍人生新樂齡\n2. 構築完善的婦幼福利\n3. 讓青年帶領雲林\n4. 打造友善的性平機制\n5. 挺勞工．顧勞權\n6. 廉能正義．施政透明\n7. 公共服務BEST\n8. 族群共融\n9. 建構動物友善空間","items":["除繼續強化雲林各項基礎建設、優化產業投資環境，擴大開發麥寮綜合商港外，並將興建高鐵體育園區，籌辦114年全國運動會，同時爭取設立雲東和雲西國家風景區。","智慧經濟：數位零距離","智慧經濟：永續農業","智慧經濟：產業永續及智慧轉型","智慧經濟：讓青年作文創的主人","智慧經濟：觀光行銷2000+","智慧經濟：暢流雲林","智慧經濟：大健康產業","低碳永續：雲林縣2030 SDGs","低碳永續：淨零減碳","低碳永續：雙語教育接軌國際","低碳永續：韌性防災","低碳永續：偏鄉無礙","低碳永續：綠能不缺電","低碳永續：拓展友善的生態保育","安全健康：建構堅韌的社會安全網","安全健康：公共場域零災害","安全健康：雲林有心、食在安心","安全健康：道安資訊智慧化","安全健康：健康 i 運動","安全健康：雲林．美哉．美在","安全健康：後疫情新生活","共融發展：活躍人生新樂齡","共融發展：構築完善的婦幼福利","共融發展：讓青年帶領雲林","共融發展：打造友善的性平機制","共融發展：挺勞工．顧勞權","共融發展：廉能正義．施政透明","共融發展：公共服務BEST","共融發展：族群共融","共融發展：建構動物友善空間"],"intro":"雲林已成功上場！\n過去四年我們推動雲林的結構性轉型，優化雲林的社福、教育、循環經濟、觀光與產業數位轉型，成功吸引超過1,777億的投資。\n未來四年我們將加速前進，讓雲林脫胎換骨。\n「2030 前進雲林」施政藍圖將聚焦於四大面向，涵蓋30項政策目標，推升雲林於2030年時蛻變為硬核且永續的農工商科技城。","allowed_text_md5":["001ed5da19b8b53e275b4d71901d4429","9e361e02d1666c0093951f2178ddee08"],"allowed_splits":[null],"old_items":null,"before_review_status":"verified","before_visibility":"public","before_is_public":true},{"id":"684f1fdb-d9db-4636-ac2e-1679ae9e4da2","claim_key":"cec-platform:2022:votetw-candidate-8ca0485af4b595a7","person_id":"8dd2e41d-075f-42f6-8e4f-d1ecaefb8419","candidate_id":"ad883f9d-b078-461e-b5b8-485689028204","name":"鍾東錦","source_url":"https://eebulletin.cec.gov.tw/111/09%E8%8B%97%E6%A0%97%E7%B8%A3/01%E7%B8%A3%E9%95%B7/%E7%B8%A3%E9%95%B7%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf","source_sha256":"665ef0a189a12ef5759cc7f4d2316803ca1327821fc18ac2a94b5d2840cdea3e","after_text":"苗栗縣政主軸：苗栗觀光科技新都心\n國際發展\n• 國際慢城營造\n• 國際慢漁運動\n• 國際智慧城市\n特色區塊\n• 苗北科技區\n• 苗中城心區\n• 苗南產創區\n• 苗西綠能區\n• 苗東觀光休閒金三角\n福利措施\n• 捐薪百萬幫助弱勢學童\n• 育兒津貼加碼2000元\n• 苗栗校園餐點質量升級\n• 啟動苗栗老宅整建服務\n• 規劃興建長照幸福園區\n• 聯合18鄉鎮市加值社會福利\n10大願景目標\n1. 全力爭取預算，挹注建設苗栗。\n2. 傳承在地文化，融合多元族群。\n3. 創新傳統產業，健全就業環境。\n4. 營造社區安全，加強治安巡防。\n5. 開創縣政商機，減輕財政赤字。\n6. 關懷弱勢族群，落實社會福利。\n7. 建立特色教育，減輕家長負擔。\n8. 加強產業轉型，活絡觀光發展。\n9. 推動都市更新，帶動工商產業。\n10. 愛護自然環境，守護苗栗好山好水。\n苗栗願景，前程似錦\n一起打贏苗栗這一仗","items":["國際發展：國際慢城營造","國際發展：國際慢漁運動","國際發展：國際智慧城市","特色區塊：苗北科技區","特色區塊：苗中城心區","特色區塊：苗南產創區","特色區塊：苗西綠能區","特色區塊：苗東觀光休閒金三角","福利措施：捐薪百萬幫助弱勢學童","福利措施：育兒津貼加碼2000元","福利措施：苗栗校園餐點質量升級","福利措施：啟動苗栗老宅整建服務","福利措施：規劃興建長照幸福園區","福利措施：聯合18鄉鎮市加值社會福利","10大願景目標：全力爭取預算，挹注建設苗栗。","10大願景目標：傳承在地文化，融合多元族群。","10大願景目標：創新傳統產業，健全就業環境。","10大願景目標：營造社區安全，加強治安巡防。","10大願景目標：開創縣政商機，減輕財政赤字。","10大願景目標：關懷弱勢族群，落實社會福利。","10大願景目標：建立特色教育，減輕家長負擔。","10大願景目標：加強產業轉型，活絡觀光發展。","10大願景目標：推動都市更新，帶動工商產業。","10大願景目標：愛護自然環境，守護苗栗好山好水。"],"intro":"苗栗縣政主軸：苗栗觀光科技新都心\n苗栗願景，前程似錦\n一起打贏苗栗這一仗","allowed_text_md5":["c1d9d1a43bc29f4ce4055b6e44c77258","848d98b7c69d439476a2de4a38a976bf"],"allowed_splits":[null],"old_items":null,"before_review_status":"verified","before_visibility":"public","before_is_public":true},{"id":"521310d2-cf75-4f41-b8d1-44b9f92a7689","claim_key":"cec-platform:2022:votetw-candidate-1d0aeac6eba935d9","person_id":"573f3182-2de7-4552-ab5d-86f1adbfc2af","candidate_id":"35176182-7997-406d-90e2-e2b28c788488","name":"翁章梁","source_url":"https://eebulletin.cec.gov.tw/111/13%E5%98%89%E7%BE%A9%E7%B8%A3/01%E7%B8%A3%E9%95%B7/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%B8%A3%E9%95%B7.pdf","source_sha256":"c8753cb7157097bdff0b51524dc590f4057f13fbc67cd61241102afc4d8a8bfb","after_text":"農工大縣、正在實現\n1.支持18歲公民權。\n2.以智慧科技技術提高農業產值、強化品牌行銷、建立冷鏈供應系統及建構農漁業用水系統。\n3.打造科學園區、無人機及航太園區發展基地，加速完成水上南靖、中埔公館工業區的開發，已開發完成之工業區機能再提升。\n4.打造與國際接軌的縣治都會環境、擴大引進大型商業設施、進行鄉鎮市景觀改造計畫及建構永續的海綿城市，營造優質安全的水域環境。\n5.成立工程美學專案辦公室，研定都市美學法規，打造嘉義城鄉美學新品牌。\n6.樂齡活動假牙與重陽敬老金持續補助及發放，擴大辦理管路安心計畫、到宅訓練外籍看護工、普及老人服務據點並提升長照服務量能、籌建身心障礙服務中心。\n7.激發教師教學熱情、強化校長專業領導、提升學生多元學習推動AI機器人及雙語課程。\n8.挹注青年活力辦理青年領袖營、青年創業就業輔導、籌建青年產業住宅。\n9.設置4處托嬰中心及9處托育中心並鼓勵企業設置幼育中心，營造親善的育兒環境。\n10.結合故宮南院建立嘉義文化品牌、旅遊環境的營造與提升、推動軸線旅遊及山林水域親子旅遊活動。","items":["支持18歲公民權。","以智慧科技技術提高農業產值、強化品牌行銷、建立冷鏈供應系統及建構農漁業用水系統。","打造科學園區、無人機及航太園區發展基地，加速完成水上南靖、中埔公館工業區的開發，已開發完成之工業區機能再提升。","打造與國際接軌的縣治都會環境、擴大引進大型商業設施、進行鄉鎮市景觀改造計畫及建構永續的海綿城市，營造優質安全的水域環境。","成立工程美學專案辦公室，研定都市美學法規，打造嘉義城鄉美學新品牌。","樂齡活動假牙與重陽敬老金持續補助及發放，擴大辦理管路安心計畫、到宅訓練外籍看護工、普及老人服務據點並提升長照服務量能、籌建身心障礙服務中心。","激發教師教學熱情、強化校長專業領導、提升學生多元學習推動AI機器人及雙語課程。","挹注青年活力辦理青年領袖營、青年創業就業輔導、籌建青年產業住宅。","設置4處托嬰中心及9處托育中心並鼓勵企業設置幼育中心，營造親善的育兒環境。","結合故宮南院建立嘉義文化品牌、旅遊環境的營造與提升、推動軸線旅遊及山林水域親子旅遊活動。"],"intro":"農工大縣、正在實現","allowed_text_md5":["1bcf631bbda9896bceb46cd10153fb71","5f6941526d1139d24555e961c7cb24f4"],"allowed_splits":[{"reviewStatus":"needs_review","releaseQuality":{"version":"cec-2022-platform-reconciliation-20260930","reasonCodes":["official_candidate_block_mismatch"]}}],"old_items":null,"before_review_status":"pending","before_visibility":"review_only","before_is_public":false}]$reviewed$::jsonb)
AS r(id uuid,claim_key text,person_id uuid,candidate_id uuid,name text,source_url text,source_sha256 text,
 after_text text,items jsonb,intro text,allowed_text_md5 jsonb,allowed_splits jsonb,old_items jsonb,
 before_review_status text,before_visibility text,before_is_public boolean);
DO $guard$
BEGIN
 IF (SELECT count(*) FROM user_platform_repairs)<>8 OR (SELECT count(DISTINCT id) FROM user_platform_repairs)<>8 OR (SELECT sum(jsonb_array_length(items)) FROM user_platform_repairs)<>176 THEN
 RAISE EXCEPTION 'Unexpected user platform review scope'; END IF;
 IF EXISTS(SELECT 1 FROM user_platform_repairs r LEFT JOIN public.person_claims c ON c.id=r.id
 LEFT JOIN public.candidates candidate ON candidate.id=c.candidate_id
 LEFT JOIN public.person_canonical_map cm ON cm.person_id=candidate.person_id
 LEFT JOIN public.person_canonical_map pm ON pm.person_id=c.person_id
 LEFT JOIN public.races race ON race.id=candidate.race_id
 LEFT JOIN public.elections election ON election.id=race.election_id
 LEFT JOIN public.platform_voting_inaugurations inauguration ON inauguration.candidate_id=candidate.id
 WHERE c.id IS NULL OR c.claim_key IS DISTINCT FROM r.claim_key OR c.claim_type IS DISTINCT FROM 'platform'
 OR c.person_id IS DISTINCT FROM r.person_id OR c.candidate_id IS DISTINCT FROM r.candidate_id
 OR c.source_url IS DISTINCT FROM r.source_url OR c.claim_json#>>'{sourceDocument,sha256}' IS DISTINCT FROM r.source_sha256
 OR candidate.is_public IS DISTINCT FROM true OR candidate.is_elected IS DISTINCT FROM true OR candidate.election_result IS DISTINCT FROM 'elected'
 OR coalesce(cm.canonical_person_id,candidate.person_id) IS DISTINCT FROM coalesce(pm.canonical_person_id,c.person_id)
 OR election.year IS DISTINCT FROM 2022 OR race.race_type IS NULL OR race.race_type NOT IN ('local_chief','county_mayor','councilor_district')
 OR election.election_type='by_election' OR coalesce(race.voting_date,election.voting_date) IS DISTINCT FROM DATE '2022-11-26'
 OR NOT (r.allowed_text_md5 ? md5(coalesce(c.claim_value,'')))
 OR NOT (r.allowed_text_md5 ? md5(coalesce(c.claim_json->>'platformText','')))
 OR (inauguration.id IS NOT NULL AND inauguration.starts_on IS DISTINCT FROM DATE '2022-12-25')
 OR (
  (c.review_status=r.before_review_status AND c.visibility=r.before_visibility AND c.is_public=r.before_is_public
   AND coalesce(c.claim_json->'items','null'::jsonb)=coalesce(r.old_items,'null'::jsonb)
   AND r.allowed_splits @> jsonb_build_array(coalesce(c.claim_json->'contentSplit','null'::jsonb)))
  OR (c.review_status='verified' AND c.visibility='public' AND c.is_public
   AND c.claim_value=r.after_text AND c.claim_json->'items'=r.items
   AND c.claim_json#>>'{contentSplit,method}'='user_official_platform_review_20260930'
   AND c.claim_json#>>'{contentSplit,reviewStatus}'='reviewed')
 ) IS NOT TRUE
 ) THEN RAISE EXCEPTION 'Reviewed platform baseline, source or identity changed'; END IF;
 -- No existing votes may be orphaned by rebuilding item keys.
 IF EXISTS(SELECT 1 FROM public.platform_fulfillment_votes v JOIN user_platform_repairs r ON r.id=v.claim_id
 JOIN public.person_claims c ON c.id=r.id WHERE c.claim_json->'items' IS DISTINCT FROM r.items) THEN
 RAISE EXCEPTION 'Existing platform votes require an explicit item mapping'; END IF;
END;
$guard$;
UPDATE public.person_claims c SET claim_value=r.after_text,review_status='verified',visibility='public',is_public=true,
 claim_json=c.claim_json||jsonb_build_object('platformText',r.after_text,'platformIntro',r.intro,'items',r.items,
 'contentSplit',jsonb_build_object('version','election-content-items-v1','method','user_official_platform_review_20260930','reviewStatus','reviewed','confidence',100),
 'platformSourceRepair',jsonb_build_object('version','user-platform-review-20260930','sourceSha256',r.source_sha256,
 'basis',CASE WHEN r.name='翁章梁' THEN 'User transcription checked against preserved CEC PDF page 1 candidate number 2; encoding replacement characters restored from official text.' ELSE 'Focused user review accepted; policy paragraphs split with headings as context and introductions excluded.' END))
 || CASE WHEN r.name='翁章梁' THEN jsonb_build_object('sourceDocument',
 ((c.claim_json->'sourceDocument')-'cropFile')||jsonb_build_object('supersededCropFile',coalesce(c.claim_json#>>'{sourceDocument,supersededCropFile}',c.claim_json#>>'{sourceDocument,cropFile}'),
 'page',1,'candidateNumber',2,'extractionMethod','reviewed_official_pdf_text_layer')) ELSE '{}'::jsonb END,
 updated_at=now()
FROM user_platform_repairs r WHERE c.id=r.id AND
 (c.claim_value IS DISTINCT FROM r.after_text OR c.claim_json->'items' IS DISTINCT FROM r.items
 OR c.claim_json#>>'{contentSplit,reviewStatus}' IS DISTINCT FROM 'reviewed');
INSERT INTO public.platform_voting_inaugurations(candidate_id,starts_on,source_url,reason)
SELECT candidate_id,DATE '2022-12-25','https://www.moi.gov.tw/News_Content.aspx?n=2&s=274773',
 '2022 elected local chief or councilor; reviewed official platform paragraphs adopted after focused user review.'
FROM user_platform_repairs ON CONFLICT(candidate_id) DO NOTHING;
DO $verify$
DECLARE r record; n integer; opened boolean; actual_items jsonb;
BEGIN
 FOR r IN SELECT * FROM user_platform_repairs LOOP
 SELECT count(*),bool_and(voting_is_open),jsonb_agg(promise_text ORDER BY display_order) INTO n,opened,actual_items
 FROM published.platform_fulfillment_results(r.id);
 IF n<>jsonb_array_length(r.items) OR opened IS DISTINCT FROM true OR actual_items IS DISTINCT FROM r.items THEN
 RAISE EXCEPTION 'User-reviewed platform items not readable/votable: %',r.id; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.public_person_claims WHERE claim_id='3d15fc9e-37bd-4846-ba85-e3920068c14c') THEN
 RAISE EXCEPTION 'Unresolved Lu source must remain private'; END IF;
END;
$verify$;
COMMIT;
